style.css:
@-moz-document domain("cinepolis.com.br") {
/* === CINÉPOLIS DARK CINEMATIC === */
  :root {
    --cp-bg: #0a0a0d;
    --cp-surface: #14141a;
    --cp-surface-2: #1c1c25;
    --cp-border: #2a2a36;
    --cp-text: #f2f2f5;
    --cp-muted: #9a9aa8;
    --cp-red: #e30613;
    --cp-red-glow: #ff2733;
    --cp-accent: #ffb800;
  }

  html, body {
    background: var(--cp-bg) !important;
    color: var(--cp-text) !important;
    font-family: "Inter", "Segoe UI", system-ui, sans-serif !important;
  }

  /* Fundo cinematográfico sutil */
  body::before {
    content: "";
    position: fixed; inset: 0;
    background:
      radial-gradient(1200px 600px at 15% -10%, rgba(227,6,19,.18), transparent 60%),
      radial-gradient(900px 500px at 110% 10%, rgba(255,184,0,.08), transparent 60%),
      linear-gradient(180deg, #0a0a0d, #08080b);
    z-index: -1;
    pointer-events: none;
  }

  /* Containers / cards / seções genéricas */
  header, nav, footer,
  section, article, aside,
  [class*="card"], [class*="Card"],
  [class*="container"], [class*="wrapper"],
  [class*="panel"], [class*="modal"],
  .row, .col, .box {
    background-color: transparent !important;
    color: var(--cp-text) !important;
    border-color: var(--cp-border) !important;
  }

  /* Header sticky com blur */
  header, .header, [class*="Header"], [class*="navbar"] {
    background: rgba(10,10,13,.75) !important;
    backdrop-filter: saturate(140%) blur(14px);
    -webkit-backdrop-filter: saturate(140%) blur(14px);
    border-bottom: 1px solid var(--cp-border) !important;
  }

  /* Cards de filmes */
  [class*="movie"], [class*="Movie"],
  [class*="poster"], [class*="Poster"],
  [class*="film"], [class*="Film"] {
    background: var(--cp-surface) !important;
    border-radius: 14px !important;
    overflow: hidden;
    border: 1px solid var(--cp-border) !important;
    transition: transform .35s ease, box-shadow .35s ease, border-color .35s ease;
  }
  [class*="movie"]:hover, [class*="Movie"]:hover,
  [class*="poster"]:hover, [class*="Poster"]:hover {
    transform: translateY(-4px) scale(1.015);
    border-color: var(--cp-red) !important;
    box-shadow:
      0 12px 40px -10px rgba(227,6,19,.45),
      0 0 0 1px rgba(227,6,19,.3) inset;
  }

  /* Imagens / posters */
  img {
    border-radius: 10px;
  }
  [class*="poster"] img, [class*="Poster"] img {
    border-radius: 0 !important;
    transition: transform .6s ease, filter .4s ease;
    filter: saturate(1.05) contrast(1.05);
  }
  [class*="poster"]:hover img {
    transform: scale(1.06);
    filter: saturate(1.15) contrast(1.1);
  }

  /* Tipografia */
  h1, h2, h3, h4 {
    color: #fff !important;
    letter-spacing: -.02em;
    font-weight: 700 !important;
  }
  h1 { font-size: clamp(2rem, 4vw, 3.25rem) !important; }
  p, span, li, label, small {
    color: var(--cp-text) !important;
  }
  .text-muted, [class*="muted"], [class*="subtitle"] {
    color: var(--cp-muted) !important;
  }

  /* Links */
  a {
    color: #fff !important;
    text-decoration: none !important;
    transition: color .2s ease;
  }
  a:hover { color: var(--cp-red-glow) !important; }

  /* Botões */
  button, .btn, [class*="button"], [type="submit"], [type="button"] {
    background: linear-gradient(135deg, var(--cp-red), #b30410) !important;
    color: #fff !important;
    border: none !important;
    border-radius: 999px !important;
    padding: .7em 1.4em !important;
    font-weight: 600 !important;
    letter-spacing: .02em;
    box-shadow: 0 8px 24px -8px rgba(227,6,19,.6);
    transition: transform .2s ease, box-shadow .2s ease, filter .2s ease;
    cursor: pointer;
  }
  button:hover, .btn:hover, [class*="button"]:hover {
    transform: translateY(-1px);
    filter: brightness(1.1);
    box-shadow: 0 12px 32px -8px rgba(255,39,51,.7);
  }
  button:active { transform: translateY(0); }

  /* Botão secundário (ghost) */
  .btn-outline, [class*="secondary"], [class*="ghost"] {
    background: transparent !important;
    border: 1px solid var(--cp-border) !important;
    color: var(--cp-text) !important;
    box-shadow: none !important;
  }
  .btn-outline:hover, [class*="secondary"]:hover {
    border-color: var(--cp-red) !important;
    color: #fff !important;
  }

  /* Inputs / selects */
  input, select, textarea {
    background: var(--cp-surface-2) !important;
    color: var(--cp-text) !important;
    border: 1px solid var(--cp-border) !important;
    border-radius: 10px !important;
    padding: .65em .9em !important;
    transition: border-color .2s ease, box-shadow .2s ease;
  }
  input:focus, select:focus, textarea:focus {
    outline: none !important;
    border-color: var(--cp-red) !important;
    box-shadow: 0 0 0 3px rgba(227,6,19,.25) !important;
  }
  ::placeholder { color: #6b6b78 !important; }

  /* Tabelas / horários de sessão */
  table { border-collapse: separate; border-spacing: 0; }
  th, td {
    background: var(--cp-surface) !important;
    border-color: var(--cp-border) !important;
    color: var(--cp-text) !important;
  }
  tr:hover td { background: var(--cp-surface-2) !important; }

  /* Badges (3D, IMAX, VIP, etc) */
  [class*="badge"], [class*="tag"], [class*="label"], [class*="chip"] {
    background: rgba(255,184,0,.12) !important;
    color: var(--cp-accent) !important;
    border: 1px solid rgba(255,184,0,.3) !important;
    border-radius: 6px !important;
    padding: 2px 8px !important;
    font-size: .75rem !important;
    font-weight: 600 !important;
    letter-spacing: .04em;
    text-transform: uppercase;
  }

  /* Scrollbar */
  ::-webkit-scrollbar { width: 10px; height: 10px; }
  ::-webkit-scrollbar-track { background: #08080b; }
  ::-webkit-scrollbar-thumb {
    background: linear-gradient(var(--cp-red), #8a0410);
    border-radius: 10px;
  }
  ::-webkit-scrollbar-thumb:hover { background: var(--cp-red-glow); }

  /* Seleção de texto */
  ::selection { background: var(--cp-red); color: #fff; }

  /* Remover fundos brancos teimosos */
  [style*="background-color: #fff"],
  [style*="background-color: white"],
  [style*="background: #fff"],
  [style*="background: white"] {
    background: var(--cp-surface) !important;
  }
}
